import java.util.*;
import org.openqa.selenium.*;
import com.qatrainer.lab.selenium.FakeDriver;

public class ExerciseVerifier {
  public List<String> verify(Class<?> cls, WebDriver driver) throws Exception {
    List<String> fails = new ArrayList<>();
    Object page = cls.getConstructor(WebDriver.class, By.class).newInstance(driver, By.className("header"));
    String title = (String) cls.getMethod("openLogo").invoke(page);
    if (!"Home".equals(title)) fails.add("title: " + title);
    FakeDriver fake = (FakeDriver) driver;
    if (fake.getActionsLog().stream().noneMatch(a -> a.startsWith("click:"))) fails.add("click missing");
    return fails;
  }
}
